/*
 * Portfolio workspace. All values come from the portfolio application service:
 * live through /api/portfolio when the viewer is signed in, otherwise the
 * static pack generated by the same service. The browser aggregates cells for
 * display only; it never creates a forecast or a financial figure.
 */
import { PORTFOLIO_PACK } from './data/portfolio-pack.js';

let data = PORTFOLIO_PACK;
let source = 'static';

async function loadLive() {
  let token = null;
  try { token = sessionStorage.getItem('railmind.token'); } catch { token = null; }
  if (!token) return;
  try {
    const response = await fetch('/api/portfolio', { headers: { Authorization: `Bearer ${token}` } });
    if (!response.ok) return;
    const dto = await response.json();
    if (Array.isArray(dto.cells)) { data = dto; source = 'live'; updateArea(); render(); }
  } catch { /* static fallback stays */ }
}

function renderProvenance() {
  const meta = data.forecastMeta;
  const node = document.getElementById('provenance');
  if (!node) return;
  const confidence = { ADEQUATE: 'Adequate calibration sample', LOW_CONFIDENCE: 'LOW CONFIDENCE: thin calibration sample', INSUFFICIENT_EVIDENCE: 'INSUFFICIENT EVIDENCE: forecast withheld' }[meta.confidence] || meta.confidence;
  node.innerHTML = `<b>${data.classification}</b> · ${data.provider} (${data.mode}) · ${source === 'live' ? 'live from /api/portfolio' : 'static pack from the same service'} · model ${meta.modelVersion} · as of ${meta.asOf} · sample ${meta.sampleSize} (${meta.forecastMeta ? '' : ''}${confidence}) · ${meta.excluded.length} excluded from calibration`;
  const gaps = document.getElementById('gap-exceptions');
  if (gaps) {
    gaps.innerHTML = data.exceptions.length
      ? `<b>${data.exceptions.length} funding-gap exception(s) at the central scenario</b>` + data.exceptions.slice(0, 8).map((x) => `<div class="gap-row gap-row--${x.severity}"><span dir="ltr">${x.initiativeId}</span><span>${x.businessArea}</span><span dir="ltr">${whole.format(x.expectedFundingGap)}</span><small>${x.decisionRequired}</small></div>`).join('')
      : '<b>No funding-gap exception at the central scenario.</b>';
  }
}

const state={portfolio:'All',area:'All',award:'All',forecastScenario:'p50',forecastArea:'All'};
const colors=['#17649b','#1f99bd','#157b72','#b97d23','#7a69ad','#bc4a50','#698595'];
const scenarioLabels={p25:'P25 · slower pace',p50:'P50 · central pace',p75:'P75 · faster pace'};
const $=id=>document.getElementById(id);
const fmt=new Intl.NumberFormat('en-US',{maximumFractionDigits:1});
const whole=new Intl.NumberFormat('en-US',{maximumFractionDigits:0});
function total(rows,key){return rows.reduce((sum,row)=>sum+(Number(row[key])||0),0)}
function money(value){return value>=1000000?fmt.format(value/1000000)+'M':whole.format(value||0)}
function pct(a,b){return b?(a/b)*100:0}
function visible(){return data.cells.filter(cell=>(state.portfolio==='All'||cell.portfolio===state.portfolio)&&(state.area==='All'||cell.businessArea===state.area)&&(state.award==='All'||cell.awardStatus===state.award))}
function grouped(rows,key){return Object.entries(rows.reduce((result,row)=>{(result[row[key]]??=[]).push(row);return result},{}))}
function updateArea(){const options=[...new Set(data.cells.filter(cell=>state.portfolio==='All'||cell.portfolio===state.portfolio).map(cell=>cell.businessArea))].sort();$('area').innerHTML='<option value="All">All business areas</option>'+options.map(value=>'<option value="'+value+'">'+value+'</option>').join('');if(!options.includes(state.area)){state.area='All'}$('area').value=state.area}
function noData(){return '<div class="empty">No aggregated portfolio values match the selected filters.</div>'}
function renderKpis(rows){const cost=total(rows,'totalCost'),spend=total(rows,'expenditure'),budget=total(rows,'budget2026'),rate=pct(spend,cost);$('count').textContent=whole.format(total(rows,'count'));$('cost').textContent=money(cost);$('spend').textContent=money(spend);$('rate').textContent=rate.toFixed(1)+'%';$('rate-note').textContent='2026 approved budget: '+money(budget);$('meter').style.width=Math.min(rate,100)+'%'}
function renderBudget(rows){const root=$('budget-chart');const groups=grouped(rows,'businessArea').map(([name,items])=>({name,cost:total(items,'totalCost'),budget:total(items,'budget2026'),spend:total(items,'expenditure')})).sort((a,b)=>b.cost-a.cost);if(!groups.length){root.innerHTML=noData();return}const max=Math.max(...groups.flatMap(item=>[item.cost,item.budget,item.spend]),1);root.innerHTML='<div class="bar-chart">'+groups.map(item=>'<div class="bar-group" title="'+item.name+' · Cost '+whole.format(item.cost)+' · Budget '+whole.format(item.budget)+' · Expenditure '+whole.format(item.spend)+'"><i class="bar bar--cost" style="height:'+Math.max(3,item.cost/max*100)+'%"></i><i class="bar bar--budget" style="height:'+Math.max(3,item.budget/max*100)+'%"></i><i class="bar bar--spend" style="height:'+Math.max(3,item.spend/max*100)+'%"></i><span class="bar-label">'+item.name+'</span></div>').join('')+'</div><div class="legend"><span><i style="background:#17649b"></i>Estimated cost</span><span><i style="background:#b97d23"></i>2026 budget</span><span><i style="background:#157b72"></i>Expenditure</span></div>'}
function renderSpending(rows){const root=$('spending-chart');const groups=grouped(rows,'businessArea').map(([name,items])=>({name,value:total(items,'expenditure')})).filter(item=>item.value>0).sort((a,b)=>b.value-a.value);if(!groups.length){root.innerHTML=noData();return}const all=total(groups,'value');let cursor=0;const segments=groups.map((item,index)=>{const start=cursor;cursor+=item.value/all*100;return colors[index%colors.length]+' '+start.toFixed(2)+'% '+cursor.toFixed(2)+'%'}).join(',');root.innerHTML='<div class="donut-layout"><div class="donut" style="--segments:conic-gradient('+segments+')"><div class="donut-center"><strong>'+money(all)+'</strong><span>Recorded expenditure</span></div></div><div class="distribution">'+groups.map((item,index)=>'<button type="button" class="'+(state.area===item.name?'active':'')+'" data-area="'+item.name+'"><i style="background:'+colors[index%colors.length]+'"></i><b>'+item.name+'</b><small>'+money(item.value)+' · '+pct(item.value,all).toFixed(1)+'%</small></button>').join('')+'</div></div>';root.querySelectorAll('[data-area]').forEach(button=>button.addEventListener('click',()=>{state.area=button.dataset.area;$('area').value=state.area;render()}))}
function renderStatus(rows){const root=$('status-chart');const all=grouped(rows,'awardStatus');const values=[['Awarded / Delivery Party Identified','Awarded / identified',''],['Not Awarded','Not awarded','warning']].map(([key,label,warning])=>({key,label,warning,items:all.find(([name])=>name===key)?.[1]||[]}));const max=Math.max(...values.map(item=>total(item.items,'count')),1);root.innerHTML='<div class="status-list">'+values.map(item=>{const count=total(item.items,'count'),cost=total(item.items,'totalCost');return '<div class="status-row"><b>'+item.label+'</b><span class="track"><i class="fill '+item.warning+'" style="width:'+count/max*100+'%"></i></span><span class="status-value">'+count+' · '+money(cost)+'</span></div>'}).join('')+'</div><div class="status-note">Award status reflects the presence or absence of an identified delivery party only. It is not a delivery-progress measure.</div>'}
function renderOutlook(rows){const values=[{year:'2026',value:total(rows,'budget2026')},{year:'2027',value:0},{year:'2028',value:0},{year:'2029',value:0},{year:'2030',value:0},{year:'2031',value:0}];const max=Math.max(...values.map(item=>item.value),1);$('outlook-chart').innerHTML='<div class="outlook">'+values.map(item=>'<div class="outlook-item" title="'+item.year+': '+whole.format(item.value)+'"><i class="outlook-bar" style="height:'+Math.max(item.value?3:0,item.value/max*100)+'%"></i><small>'+item.year+'</small></div>').join('')+'</div><div class="legend"><span><i style="background:#b97d23"></i>Approved / recorded allocation by year</span></div>'}

function forecastVisible(){return data.cells.filter(cell=>(state.portfolio==='All'||cell.portfolio===state.portfolio)&&(state.area==='All'||cell.businessArea===state.area)&&(state.award==='All'||cell.awardStatus===state.award))}
function forecastGroups(rows){return grouped(rows,'businessArea').map(([name,items])=>({name,p25:total(items,'forecastP25'),p50:total(items,'forecastP50'),p75:total(items,'forecastP75'),budget:total(items,'forecastEligibleBudget'),eligible:total(items,'forecastEligibleCount')})).filter(item=>item.p25>0||item.p50>0||item.p75>0)}
function renderForecastDetail(item,scenario){const heading=$('forecast-detail-heading'),copy=$('forecast-detail-copy'),detail=$('forecast-detail');const name=item.name||'All visible business areas';const value=item[scenario];const allocationComparison=item.budget-value;heading.textContent=name;copy.textContent=state.forecastArea==='All'?'Aggregated scenario outlook for the current portfolio filters.':'Click another business area to compare its scenario exposure.';detail.innerHTML='<div class="forecast-detail-hero"><small>'+scenarioLabels[scenario]+'</small><strong>'+money(value)+'</strong><span>Additional expenditure through '+data.forecastMeta.horizon+'</span></div><div class="forecast-detail-grid">'+['p25','p50','p75'].map(key=>'<div class="forecast-detail-cell '+(key===scenario?'is-active':'')+'"><small>'+scenarioLabels[key].split(' · ')[0]+'</small><b>'+money(item[key])+'</b></div>').join('')+'</div><div class="forecast-detail-meta"><div><small>Scenario range</small><b>'+money(item.p25)+' to '+money(item.p75)+'</b></div><div><small>Gross allocation comparison</small><b>'+(allocationComparison>=0?money(allocationComparison)+' above selected outlook':'Selected outlook exceeds by '+money(Math.abs(allocationComparison)))+'</b></div></div>'}
function renderForecast(rows){const eligible=total(rows,'forecastEligibleCount'),p25=total(rows,'forecastP25'),p50=total(rows,'forecastP50'),p75=total(rows,'forecastP75'),budget=total(rows,'forecastEligibleBudget'),cover=budget-p50;$('forecast-p25').textContent=eligible?money(p25):'—';$('forecast-p50').textContent=eligible?money(p50):'—';$('forecast-p75').textContent=eligible?money(p75):'—';$('forecast-cover').textContent=eligible?money(Math.abs(cover)):'—';$('forecast-cover-note').textContent=!eligible?'No eligible awarded initiatives in view':cover>=0?'Gross allocation is above P50 additional outlook; not a remaining balance':'P50 additional outlook exceeds gross 2026 allocation';const controls=$('forecast-scenario-controls'),root=$('forecast-chart');let groups=forecastGroups(rows);if(!groups.length){controls.innerHTML='';root.innerHTML=noData();$('forecast-detail-heading').textContent='No scenario detail available';$('forecast-detail-copy').textContent='Update the filters to view eligible awarded initiatives.';$('forecast-detail').innerHTML='';$('forecast-method').innerHTML='<div><small>Coverage</small><b>No eligible awarded initiative matches the selected filters.</b></div>';return}if(!Object.hasOwn(scenarioLabels,state.forecastScenario))state.forecastScenario='p50';if(state.forecastArea!=='All'&&!groups.some(item=>item.name===state.forecastArea))state.forecastArea='All';const scenario=state.forecastScenario;groups=groups.sort((a,b)=>b[scenario]-a[scenario]);const max=Math.max(...groups.map(item=>item.p75),1);controls.innerHTML=Object.entries(scenarioLabels).map(([key,label])=>'<button type="button" class="scenario-tab '+(key===scenario?'is-active':'')+'" data-forecast-scenario="'+key+'" aria-pressed="'+(key===scenario)+'">'+label+'</button>').join('');root.innerHTML='<div class="scenario-chart">'+groups.map(item=>'<button type="button" class="scenario-row '+(state.forecastArea===item.name?'is-selected':'')+'" data-forecast-area="'+item.name+'" aria-pressed="'+(state.forecastArea===item.name)+'" title="'+item.name+' · P25 '+money(item.p25)+' · P50 '+money(item.p50)+' · P75 '+money(item.p75)+'"><b class="scenario-name">'+item.name+'</b><span class="scenario-track"><i class="scenario-envelope" style="width:'+item.p75/max*100+'%"></i><i class="scenario-floor" style="width:'+item.p25/max*100+'%"></i><i class="scenario-fill scenario-fill--'+scenario+'" style="width:'+item[scenario]/max*100+'%"></i><i class="scenario-central-marker" style="left:calc('+item.p50/max*100+'% - 1px)"></i></span><small class="scenario-value">'+money(item[scenario])+'</small></button>').join('')+'</div><p class="scenario-chart-note">The pale envelope shows the P25–P75 range; the coloured bar shows the selected scenario; the white marker shows P50.</p>';controls.querySelectorAll('[data-forecast-scenario]').forEach(button=>button.addEventListener('click',()=>{state.forecastScenario=button.dataset.forecastScenario;renderForecast(forecastVisible())}));root.querySelectorAll('[data-forecast-area]').forEach(button=>button.addEventListener('click',()=>{state.forecastArea=button.dataset.forecastArea;renderForecast(forecastVisible())}));const selected=state.forecastArea==='All'?{name:'All visible business areas',p25,p50,p75,budget,eligible}:groups.find(item=>item.name===state.forecastArea);if(selected)renderForecastDetail(selected,scenario);$('forecast-method').innerHTML='<div><small>As-of / horizon</small><b>'+data.forecastMeta.asOf+' to '+data.forecastMeta.horizon+'</b></div><div><small>Calibration cohort</small><b>'+data.forecastMeta.sampleSize+' awarded initiatives with positive expenditure and at least '+(data.forecastMeta.minimumScheduleProgress*100).toFixed(0)+'% schedule progress</b></div><div><small>Pace factors · P25 / P50 / P75</small><b>'+data.forecastMeta.paceP25.toFixed(2)+' / '+data.forecastMeta.paceP50.toFixed(2)+' / '+data.forecastMeta.paceP75.toFixed(2)+' × schedule progress</b></div><div><small>Eligibility</small><b>'+whole.format(eligible)+' active awarded initiatives; unawarded and ended initiatives excluded</b></div>'}

function render(){const rows=visible();renderKpis(rows);renderBudget(rows);renderSpending(rows);renderStatus(rows);renderOutlook(rows);renderForecast(forecastVisible());renderProvenance()}
$('portfolio').addEventListener('change',event=>{state.portfolio=event.target.value;updateArea();render()});$('area').addEventListener('change',event=>{state.area=event.target.value;render()});$('award').addEventListener('change',event=>{state.award=event.target.value;render()});$('reset').addEventListener('click',()=>{state.portfolio='All';state.area='All';state.award='All';$('portfolio').value='All';$('award').value='All';updateArea();render()});updateArea();render();
loadLive();
